/* eslint-disable n/no-sync */

'use strict';

// MODULES //

var mkdir = require( 'fs' ).mkdirSync;
var resolve = require( 'path' ).resolve;
var dirname = require( 'path' ).dirname;
var existsSync = require( '@stdlib/fs/exists' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var spec2svg = require( '@stdlib/plot/vega/base/spec2svg' );


// MAIN //

/**
* Renders a Vega specification to an SVG file.
*
* @param {Object} spec - Vega specification
* @param {string} outputPath - file path for the SVG output
* @param {Callback} clbk - callback to invoke upon completion
*
* @example
* var spec2svgFile = require( '@stdlib/plot/vega/base/spec2svg-file' );
*
* var spec = {
*     '$schema': 'https://vega.github.io/schema/vega/v6.json',
*     'width': 400,
*     'height': 30,
*     'padding': 5,
*     'title': {
*         'text': 'Hello World'
*     },
*     'marks': []
* };
*
* spec2svgFile( spec, './output.svg', done );
*
* function done( error ) {
*     if ( error ) {
*         throw error;
*     }
*     console.log( 'SVG written successfully.' );
* }
*/
function spec2svgFile( spec, outputPath, clbk ) {
	var fpath;
	var dir;
	var err;

	fpath = resolve( outputPath );
	dir = dirname( fpath );
	if ( !existsSync( dir ) ) {
		mkdir( dir, {
			'recursive': true
		});
	}
	spec2svg( spec, onSVG );

	/**
	* Callback invoked upon rendering an SVG.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @param {string} svg - rendered SVG string
	* @returns {void}
	*/
	function onSVG( error, svg ) {
		if ( error ) {
			return clbk( error );
		}
		err = writeFileSync( fpath, svg );
		if ( err instanceof Error ) {
			return clbk( err );
		}
		return clbk( null );
	}
}


// EXPORTS //

module.exports = spec2svgFile;
